// CSD_RATIONALE_BEGIN
// Root cause of 52% ceiling: premature IsCompletePrefix closure on short SQL.
// The model emits "SELECT city" (2 constrained tokens, syntactically complete),
// IsCompletePrefix fires, CloseConstrainedSpan closes immediately, and we get
// wrong SQL missing WHERE/GROUP BY/HAVING. Avg generated tokens = 8.84 confirms
// this: preamble (3-5 tokens) + SQL content (3-6 tokens) = premature closure.
//
// This attempt fixes premature closure with SpeculativeConstrainedRollout:
// when IsCompletePrefix fires on short SQL (|current| <= 20), we speculate
// 5 tokens forward. If hitComplete=true (a longer valid SQL exists within 5
// tokens), we continue generating. If hitComplete=false, we close. This
// defers closure on short SQL where the model would continue to a longer
// correct answer, while closing quickly for SQL that genuinely ends.
//
// Changes from attempt 43 (best at 52%):
// 1. Speculation-based deferral when |current| <= 20 and budget allows (steps+7 <= maxSteps).
// 2. Improved guidance: explicit instructions for COUNT(*) vs COUNT(DISTINCT),
//    complete clause inclusion (FROM/WHERE/GROUP BY/HAVING), and ORDER BY LIMIT.
// 3. Everything else unchanged: boost=6.0 (99% syntax), 5-step preamble,
//    CloseSpanWithinBudget(80) safety net.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Only flips insideConstrainedOut=true via RenderedEndsWith("<<"),
//   setting currentConstrainedOut := [] which satisfies IsValidPrefix([]) by precondition.
//   EOS break leaves insideConstrainedOut false; implication is vacuous.
//
// Phase 2 OpenConstrainedSpan: helper sets currentConstrainedOut := [],
//   IsValidPrefix([]) holds by precondition.
//
// Phase 3 main loop:
//   doSpeculate + hitComplete + non-EOS: SpeculativeConstrainedRollout does not modify
//   currentConstrainedOut or insideConstrainedOut (restores logits; no state commit).
//   GroupBoostedConstrainedStep hard-masks to parser-valid tokens plus EOS.
//   AppendConstrainedToken extends currentConstrainedOut by one valid token, preserving
//   IsValidPrefix by parser monotone-extension contract.
//   doSpeculate + hitComplete + EOS: CloseConstrainedSpan sets insideConstrainedOut := false
//   (implication vacuous) or break leaves unchanged valid prefix.
//   doSpeculate + !hitComplete + close: CloseConstrainedSpan sets insideConstrainedOut := false.
//   !doSpeculate + close: same.
//   Non-complete else branch: GroupBoostedConstrainedStep + AppendConstrainedToken preserve validity.
//   EOS + IsCompletePrefix + close: CloseConstrainedSpan sets insideConstrainedOut := false.
//
// Phase 4 CloseSpanWithinBudget: postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut); !insideOut ==> currentOut == [].
//
// Invariant 2: progress  |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs +1 step, appends at most 1 token. Net 1:1 max.
// Phase 2: OpenConstrainedSpan costs +1 step, appends exactly 1 "<<" token. Net 1:1.
// Phase 3:
//   doSpeculate + hitComplete path: SpeculativeConstrainedRollout costs +stepsUsed (>= 1)
//   steps with no visible token appended. GroupBoostedConstrainedStep costs +1 step.
//   AppendConstrainedToken appends 1 token. Total: generated grew by at most 1,
//   steps grew by stepsUsed+1 >= 2. Progress maintained since generated growth <= step growth.
//   doSpeculate + !hitComplete path: spec costs +stepsUsed, close costs +1. Generated grows
//   by at most 1 (">>" from CloseConstrainedSpan). Steps grow by stepsUsed+1 >= 2. ✓
//   !doSpeculate close path: steps += 1, generated += at most 1. Net 1:1 max. ✓
//   Non-complete branch: steps += 1 (GroupBoostedConstrainedStep), generated += 1
//   (AppendConstrainedToken) or 0 (EOS). Net at most 1:1. ✓
// Phase 4: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated| + budget;
//   steps := steps + closeBudget. Invariant maintained. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate correct SQL for the question. Format: SQL: <<query>>. Write complete SQL: include FROM clause with exact table name, WHERE clause when filtering, GROUP BY + HAVING when aggregating groups, ORDER BY col DESC LIMIT 1 for max/min questions. Use COUNT(*) for total row counts; use COUNT(DISTINCT col) only when the question asks for different/unique/distinct values. Use only exact table and column names from the provided schema. Output the SQL between << and >>.");

var steps: nat := 0;

// Phase 1: Short free preamble (at most 5 steps) to let model emit "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard constrained control with schema-token boosting
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  if parser.IsCompletePrefix(currentConstrainedOut) {
    // For short SQL, speculate to defer premature closure when a longer valid SQL exists
    var doSpeculate := |currentConstrainedOut| <= 20 && steps + 7 <= maxSteps;
    if doSpeculate {
      var _, _, hitComplete, _, stepsUsed :=
        helpers.SpeculativeConstrainedRollout(lm, parser, constrainedPrompt, currentConstrainedOut, 5, eosToken);
      steps := steps + stepsUsed;
      if hitComplete {
        // A longer valid SQL exists within 5 tokens — continue generating
        var next := helpers.GroupBoostedConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
        );
        steps := steps + 1;
        if next == eosToken {
          if steps < maxSteps {
            var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
            generated := cg;
            insideConstrainedOut := ci;
            currentConstrainedOut := cc;
            steps := steps + 1;
          }
          break;
        } else {
          var ag, ai, ac := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        }
      } else {
        // No longer complete SQL reachable in 5 steps — close now
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
        break;
      }
    } else {
      // Long SQL (> 20 tokens) or insufficient budget — close immediately
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
      break;
    }
  } else {
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget as safety net
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 {
    closeBudget := remaining;
  } else {
    closeBudget := 80;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

